import httpx

async def generate(ctx, api):
    BASE = "https://autodl.art/api/v1"
    DEFAULT_WORKFLOW_ID = "minimax_h3_lightx2v_no_pic"
    API_KEY = ctx.get("api_key") or api.get("get_api_key", lambda: "")() or "3jfV2WXEzzGkSW1gcuZwAtTAMbDhruqwgphMu9mXQ5EIKapd"
    headers = {"Authorization": API_KEY, "Content-Type": "application/json"}

    # 实测 AutoDL 远端仅 480p 档稳定可用（720p/1080p 已被白名单下线），
    # 任何非法档位统一降级到同向 480p，避免必失败参数烧掉审批轮次
    _RES_MAP = {
        "480p": "480p竖", "720p": "480p竖", "1080p": "480p竖",
        "480p竖": "480p竖", "480p横": "480p横",
        "720p竖": "480p竖", "720p横": "480p横",
        "1080p竖": "480p竖", "1080p横": "480p横",
    }

    dyn = ctx.get("dynamic_inputs") or {}
    prompt = (ctx.get("prompt") or "").strip()
    task_id = (ctx.get("task_id") or dyn.get("task_id") or "").strip()
    # workflow_id 参数真正生效：params 选择的工作流优先于默认值
    workflow_id = str(ctx.get("workflow_id") or dyn.get("workflow_id") or DEFAULT_WORKFLOW_ID).strip() or DEFAULT_WORKFLOW_ID

    # —— 查询模式（秒回，不许 sleep）——
    if task_id and not prompt:
        async with httpx.AsyncClient(timeout=15) as client:
            r = await client.get(f"{BASE}/comfyui/comfyui_workflow/result/{task_id}", headers=headers)
            r.raise_for_status()
            data = (r.json() or {}).get("data", {}) or {}
            status = str(data.get("status") or "").upper()
            url = None
            for item in (data.get("results") or []):
                if isinstance(item, dict) and item.get("type") == "video" and item.get("url"):
                    url = item["url"]
                    break
            if not url and data.get("results"):
                first = data["results"][0]
                url = first.get("url") if isinstance(first, dict) else (first if isinstance(first, str) else None)
            if url:
                return {"video_url": url, "status": data.get("status"), "task_id": task_id}
            if status in ("FAILED", "ERROR", "FAIL", "CANCELLED"):
                raise RuntimeError(f"AutoDL 任务失败 task_id={task_id}: {str(data)[:300]}")
            return {"video_url": None, "status": data.get("status") or "QUEUED", "task_id": task_id}

    if not prompt:
        raise ValueError("缺少 prompt")

    try:
        duration = max(3, min(10, int(ctx.get("duration") or 5)))
    except (ValueError, TypeError):
        duration = 5
    _raw_res = str(ctx.get("resolution") or "480p竖").strip() or "480p竖"
    res = _RES_MAP.get(_raw_res, "480p竖")
    body = {
        "prompt": prompt,
        "duration": duration,
        "resolution": res,
    }

    # 首帧/参考图/尾帧（http(s)/data: 均支持，由框架自动内联本地文件）
    ordered = []
    for k in ("first_frame", "first_frame_url"):
        v = ctx.get(k) or dyn.get(k)
        if isinstance(v, str) and v.startswith(("http://", "https://", "data:")):
            ordered.append(v)
            break
    _refs = ctx.get("reference_images") or dyn.get("reference_images") or []
    if isinstance(_refs, str):
        _refs = [_refs]
    for u in _refs:
        if isinstance(u, str) and u.startswith(("http://", "https://", "data:")):
            ordered.append(u)
    for k in ("last_frame", "last_frame_url"):
        v = ctx.get(k) or dyn.get(k)
        if isinstance(v, str) and v.startswith(("http://", "https://", "data:")):
            ordered.append(v)
            break
    seen, uniq = set(), []
    for u in ordered:
        if u not in seen:
            seen.add(u)
            uniq.append(u)

    # 纯文本工作流不接受图像参数：提前明错（避免 AutoDL 晦涩报错 + Agent 空转重试）
    if uniq and "no_pic" in workflow_id:
        raise RuntimeError(
            f"当前工作流「{workflow_id}」是纯文本工作流，不支持首帧/参考图/尾帧。"
            f"请把 workflow_id 切换为图生视频工作流（如 minimax_h3_image_audio_to_video_v2_15s），"
            f"或改用「AutoDL H3 图音生视频 v2 (15s)」源后重试。"
        )
    for i, u in enumerate(uniq[:9]):
        body[f"ref_image_{i}"] = u

    # 提交即返（后台轮询接管，勿阻塞等终态）
    async with httpx.AsyncClient(timeout=20) as client:
        r = await client.post(f"{BASE}/comfyui/comfyui_workflow/{workflow_id}", json=body, headers=headers)
        r.raise_for_status()
        resp = r.json() or {}
        if resp.get("code") not in (None, "Success", "success"):
            msg = str(resp.get("msg") or resp)[:300]
            if "未定义的参数" in msg:
                msg += "（该工作流不接受当前参数：多为参考图/首帧，或 workflow_id 与源不匹配）"
            raise RuntimeError(f"AutoDL 提交失败: {msg}")
        new_id = (resp.get("data") or {}).get("task_id")
        if not new_id:
            raise RuntimeError(f"AutoDL 未返回 task_id: {str(resp)[:400]}")
        result = {"video_url": None, "task_id": new_id, "status": "SUBMITTED"}
        if res != _raw_res:
            result["degraded_from"] = _raw_res
            result["resolution"] = res
        return result
